{
  "name": "Rheodyne MXII 多通切换阀",
  "name_en": "Rheodyne MXII multiport valve",
  "manufacturer": "Rheodyne / IDEX Health & Science",
  "description": "这是一种电动多通切换阀，用于在多个液路端口之间切换流体通道。实验室中常用于色谱、流动分析及自动化液路系统中的流路选择、样品切换和溶剂导向。该证据表明驱动面向 Rheodyne MXII 系列阀，并已在 MXX778-605 十口阀上测试。",
  "description_en": "This is a motorized multiport valve used to switch fluid flow between multiple ports. In laboratories it is commonly used for flow-path selection, sample switching, and solvent routing in chromatography, flow analysis, and automated fluidic systems. The evidence indicates support for the Rheodyne MXII valve family and testing on the MXX778-605 10-port valve.",
  "tag_hints": [
    "multiport valve",
    "fluid routing",
    "10-port valve",
    "chromatography",
    "sample switching",
    "serial-controlled valve",
    "Rheodyne MXII"
  ],
  "actions": [
    {
      "action_name": "auto-stripped_hex",
      "description": "将十进制端口或目标值转换为用于阀门通信的去前缀大写十六进制字符串。",
      "description_en": "Convert a decimal port or target value into an uppercase hexadecimal string without the prefix for valve communication."
    },
    {
      "action_name": "auto-wait_ready",
      "description": "等待阀门报告已就绪，可以接收下一条控制指令。",
      "description_en": "Wait until the valve reports that it is ready to accept the next control command."
    },
    {
      "action_name": "auto-message_builder",
      "description": "构建用于读取阀位或切换端口的阀门通信消息。",
      "description_en": "Build a valve communication message for reading the current position or changing the port."
    },
    {
      "action_name": "auto-read_message",
      "description": "读取阀门返回的通信响应。",
      "description_en": "Read the communication response returned by the valve."
    },
    {
      "action_name": "auto-write_message",
      "description": "向阀门发送通信消息。",
      "description_en": "Send a communication message to the valve."
    },
    {
      "action_name": "auto-response_interpret",
      "description": "解析阀门响应，将其转换为当前端口或就绪状态信息。",
      "description_en": "Interpret the valve response and convert it into the current port or ready-state information."
    },
    {
      "action_name": "auto-change_port",
      "description": "将阀门切换到指定端口位置。",
      "description_en": "Change the valve to the specified port position."
    },
    {
      "action_name": "auto-get_port",
      "description": "获取当前阀位端口。",
      "description_en": "Get the current valve port position."
    }
  ]
}

